   543	/*
   544	** The following routine implements the rough equivalent of localtime_r()
   545	** using whatever operating-system specific localtime facility that
   546	** is available.  This routine returns 0 on success and
   547	** non-zero on any kind of error.
   548	**
   549	** If the sqlite3GlobalConfig.bLocaltimeFault variable is non-zero then this
   550	** routine will always fail.  If bLocaltimeFault is nonzero and
   551	** sqlite3GlobalConfig.xAltLocaltime is not NULL, then xAltLocaltime() is
   552	** invoked in place of the OS-defined localtime() function.
   553	**
   554	** EVIDENCE-OF: R-62172-00036 In this implementation, the standard C
   555	** library function localtime_r() is used to assist in the calculation of
   556	** local time.
   557	*/
   558	static int osLocaltime(time_t *t, struct tm *pTm){
   559	  int rc;
   560	#if !HAVE_LOCALTIME_R && !HAVE_LOCALTIME_S
   561	  struct tm *pX;
